package com.deskweave.model;

import java.io.Serializable;
import java.time.LocalDateTime;
import java.util.Objects;

/**
 * Actionable space recommendation generated by the Capacity Planning module.
 */
public class CapacityRecommendation implements Serializable {

    private static final long serialVersionUID = 1L;

    private final int recId;
    private final LocalDateTime generatedAt;
    private final RecommendationCategory category;
    private final Severity severity;
    private final int floor;
    private final WorkspaceType workspaceType;
    private final double metricValue;
    private final String summary;
    private final String suggestedAction;

    public CapacityRecommendation(int recId, LocalDateTime generatedAt, RecommendationCategory category,
                                  Severity severity, int floor, WorkspaceType workspaceType,
                                  double metricValue, String summary, String suggestedAction) {
        this.recId = recId;
        this.generatedAt = Objects.requireNonNull(generatedAt, "generatedAt must not be null");
        this.category = Objects.requireNonNull(category, "category must not be null");
        this.severity = Objects.requireNonNull(severity, "severity must not be null");
        this.floor = floor;
        this.workspaceType = Objects.requireNonNull(workspaceType, "workspaceType must not be null");
        this.metricValue = metricValue;
        this.summary = Objects.requireNonNull(summary, "summary must not be null").trim();
        this.suggestedAction = Objects.requireNonNull(suggestedAction, "suggestedAction must not be null").trim();
    }

    public int getRecId() {
        return recId;
    }

    public LocalDateTime getGeneratedAt() {
        return generatedAt;
    }

    public RecommendationCategory getCategory() {
        return category;
    }

    public Severity getSeverity() {
        return severity;
    }

    public int getFloor() {
        return floor;
    }

    public WorkspaceType getWorkspaceType() {
        return workspaceType;
    }

    public double getMetricValue() {
        return metricValue;
    }

    public String getSummary() {
        return summary;
    }

    public String getSuggestedAction() {
        return suggestedAction;
    }

    @Override
    public String toString() {
        return "[" + severity + "] " + category + " (Floor " + floor + " " + workspaceType + "): " + summary;
    }
}
